package lk.repairdesk.api.controller; import jakarta.validation.Valid; import lk.repairdesk.api.domain.*; import lk.repairdesk.api.dto.WorkDtos.*; import lk.repairdesk.api.service.WorkService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api") public class WorkController {private final WorkService s;public WorkController(WorkService s){this.s=s;}@PostMapping("/repairs/{id}/diagnosis") @PreAuthorize("hasAnyRole('TECHNICIAN','MANAGER','ADMIN')") ResponseEntity<Diagnosis> diagnosis(@PathVariable Long id,@Valid @RequestBody DiagnosisRequest x){return ResponseEntity.status(HttpStatus.CREATED).body(s.diagnose(id,x));}@PostMapping("/repairs/{id}/quotations") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") ResponseEntity<Quotation> quote(@PathVariable Long id,@Valid @RequestBody QuotationRequest x){return ResponseEntity.status(HttpStatus.CREATED).body(s.quote(id,x));}@GetMapping("/repairs/{id}/quotations") List<Quotation> quotes(@PathVariable Long id){return s.quotations(id);}@PostMapping("/recommendations") Map recommendation(@Valid @RequestBody RecommendationRequest x){return s.recommendation(x);}}